// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/*
    BLUE SHIBA INU Token (BLUE)
    Telegram: https://t.me/Blueshibaainu
*/

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract BLUE_SHIBA_INU {
    string public constant name = "BLUE SHIBA INU";
    string public constant symbol = "BLUE";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    address public marketingWallet;
    address public operationsManager;
    address public exchangePool;

    uint256 public buyContribution;
    uint256 public sellContribution;
    uint256 public maxMove;
    uint256 public maxHold;
    uint256 public collectThreshold;

    mapping(address => uint256) public userBalance;
    mapping(address => mapping(address => uint256)) public spendPermit;
    mapping(address => bool) private bypassRestrictions;

    IUniswapV2Router02 private immutable dexRouter;
    bool public marketOpen = false;

    event TokenMove(address indexed from, address indexed to, uint256 value);
    event SpendPermitUpdated(address indexed holder, address indexed operator, uint256 value);
    event MarketInitialized();
    event LeadershipTransferred(address indexed previous, address indexed next);

    modifier onlyLeader() {
        require(msg.sender == operationsManager, "Management clearance required");
        _;
    }

    constructor() {
        operationsManager = msg.sender;
        marketingWallet = msg.sender;
        totalSupply = 1_000_000_000 * (10 ** decimals);
        buyContribution = 5;
        sellContribution = 5;
        maxMove = totalSupply / 100;
        maxHold = totalSupply / 50;
        collectThreshold = totalSupply / 1000;

        userBalance[msg.sender] = totalSupply;
        bypassRestrictions[msg.sender] = true;
        bypassRestrictions[address(this)] = true;

        dexRouter = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);

        emit TokenMove(address(0), msg.sender, totalSupply);
    }

    function updateLeadership(address newLeader) external onlyLeader {
        require(newLeader != address(0), "Invalid leader address");
        emit LeadershipTransferred(operationsManager, newLeader);
        operationsManager = newLeader;
    }

    function grantSpendPermit(address operator, uint256 amount) public returns (bool) {
        spendPermit[msg.sender][operator] = amount;
        emit SpendPermitUpdated(msg.sender, operator, amount);
        return true;
    }

    function moveTokens(address recipient, uint256 amount) public returns (bool) {
        _processMove(msg.sender, recipient, amount);
        return true;
    }

    function operateMove(address sender, address recipient, uint256 amount) public returns (bool) {
        require(spendPermit[sender][msg.sender] >= amount, "Insufficient permit");
        _processMove(sender, recipient, amount);
        spendPermit[sender][msg.sender] -= amount;
        return true;
    }

    function _processMove(address sender, address recipient, uint256 amount) internal {
        require(marketOpen || bypassRestrictions[sender] || bypassRestrictions[recipient], "Market not yet open");
        require(sender != address(0) && recipient != address(0), "Invalid address");
        require(amount > 0, "Invalid amount");

        if (!bypassRestrictions[sender] && !bypassRestrictions[recipient]) {
            require(amount <= maxMove, "Exceeds move limit");
            require(userBalance[recipient] + amount <= maxHold, "Exceeds hold limit");
        }

        uint256 contributionAmount = 0;

        if (!bypassRestrictions[sender] && !bypassRestrictions[recipient]) {
            if (recipient == exchangePool) {
                contributionAmount = (amount * sellContribution) / 100;
            } else if (sender == exchangePool) {
                contributionAmount = (amount * buyContribution) / 100;
            }
        }

        uint256 finalAmount = amount - contributionAmount;
        userBalance[sender] -= amount;
        userBalance[recipient] += finalAmount;

        if (contributionAmount > 0) {
            userBalance[address(this)] += contributionAmount;
            emit TokenMove(sender, address(this), contributionAmount);
        }

        emit TokenMove(sender, recipient, finalAmount);

        if (userBalance[address(this)] >= collectThreshold) {
            _collectContributions();
        }
    }

    function _collectContributions() private {
        uint256 tokenBalance = userBalance[address(this)];
        if (tokenBalance == 0) return;

        grantSpendPermit(address(dexRouter), tokenBalance);
        
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = dexRouter.WETH();

        dexRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            marketingWallet,
            block.timestamp
        );
    }

    function initializeMarket() external onlyLeader {
        require(!marketOpen, "Market already open");
        
        address factory = dexRouter.factory();
        exchangePool = IUniswapV2Factory(factory).getPair(address(this), dexRouter.WETH());
        
        require(exchangePool != address(0), "Pool not found");
        
        marketOpen = true;
        emit MarketInitialized();
    }

    function setExchangePool(address pool) external onlyLeader {
        require(!marketOpen, "Market already open");
        require(pool != address(0), "Invalid pool");
        exchangePool = pool;
    }

    function updateContributions(uint256 newBuy, uint256 newSell) external onlyLeader {
        require(newBuy <= 5 && newSell <= 5, "Excessive rates");
        buyContribution = newBuy;
        sellContribution = newSell;
    }

    function removeLimits() external onlyLeader {
        maxMove = totalSupply;
        maxHold = totalSupply;
    }

    function setRestrictionStatus(address account, bool status) external onlyLeader {
        bypassRestrictions[account] = status;
    }

    function updateMarketing(address wallet) external onlyLeader {
        require(wallet != address(0), "Invalid wallet");
        marketingWallet = wallet;
    }

    function collectEther() external onlyLeader {
        payable(operationsManager).transfer(address(this).balance);
    }

    receive() external payable {}
}
